CREATE OR REPLACE FUNCTION public.reconcile_sales_payment(p_id uuid,p_key text,p_amount numeric,p_ref text,p_date timestamptz) RETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r public.invoices; BEGIN SELECT * INTO r FROM public.invoices WHERE id=p_id FOR UPDATE; IF NOT FOUND OR r.kind='creditnota' OR p_amount<=0 OR abs((r.total-coalesce(r.paid_amount,0))-p_amount)>=0.005 THEN RETURN false; END IF; INSERT INTO public.ponto_reconciliations(transaction_key,invoice_id,amount,payment_ref,paid_at) VALUES(p_key,p_id,p_amount,p_ref,p_date) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN false; END IF; UPDATE public.invoices SET paid_amount=r.total,paid_at=p_date WHERE id=p_id; RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.reconcile_sales_payment(uuid,text,numeric,text,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.reconcile_sales_payment(uuid,text,numeric,text,timestamptz) TO authenticated,service_role;